targets.expr:
sum(max by (server_name) (
    amd_gpu_average_package_power{server_name=~"$host"}
    or amd_gpu_package_power{server_name=~"$host"}
    or (
        (node_hwmon_power_watt{server_name=~"$host"} or node_hwmon_power_average_watt{server_name=~"$host"})
        and on (instance, chip) node_hwmon_chip_names{chip_name="amdgpu"}
    )
))

